local MoldDryingOvenMaker = {}
local PRODUCTS = {
    iron_molddryingoven = { name = "Železni sušilna peč za kalupe", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sušilna peč za kalupe za livarje." },
    bronze_molddryingoven = { name = "Bronast sušilna peč za kalupe", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sušilna peč za kalupe za livarje." },
    silver_molddryingoven = { name = "Srebrn sušilna peč za kalupe", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sušilna peč za kalupe za livarje." },
    gilded_molddryingoven = { name = "Pozlačen sušilna peč za kalupe", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sušilna peč za kalupe za livarje." },
    jewel_set_molddryingoven = { name = "Draguljast sušilna peč za kalupe", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sušilna peč za kalupe za livarje." },
    royal_sovereign_molddryingoven = { name = "Kraljevski suveren sušilna peč za kalupe", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sušilna peč za kalupe z biseri za krono." },
}
